import{_ as r}from"./chunks/printers.ue_4EMK9.js";import{_ as o,o as e,c as a,a2 as l}from"./chunks/framework.DSc8fo6x.js";const m=JSON.parse('{"title":"Принтер чеков и этикеток","description":"","frontmatter":{},"headers":[],"relativePath":"ru/printerler.md","filePath":"ru/printerler.md"}'),n={name:"ru/printerler.md"};function i(s,t,d,g,h,p){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="принтер-чеков-и-этикеток" tabindex="-1">Принтер чеков и этикеток <a class="header-anchor" href="#принтер-чеков-и-этикеток" aria-label="Permalink to &quot;Принтер чеков и этикеток&quot;">​</a></h1><p>Один термопринтер (напр. <strong>Xprinter XP-365B</strong>) может печатать и чеки, и этикетки со штрихкодом.</p><h2 id="подключение" tabindex="-1">Подключение <a class="header-anchor" href="#подключение" aria-label="Permalink to &quot;Подключение&quot;">​</a></h2><ol><li>Подключите принтер по USB и установите его <strong>драйвер для Windows</strong> (диск из коробки или сайт производителя). Принтер должен появиться в списке «Принтеры» Windows.</li><li>Kassa → <strong>Настройки → Принтеры</strong>: <ul><li><strong>Принтер чеков</strong> и <strong>Принтер этикеток (штрихкодов)</strong> — выберите устройство из списка (можно одно и то же);</li><li><strong>Размер этикетки</strong> (в карточке «Продажа и печать») — размер этикетки в рулоне (напр. 40×30);</li><li>по желанию: <strong>Печатать чек автоматически после продажи</strong>, <strong>Открывать денежный ящик при оплате наличными</strong>.</li></ul></li><li><strong>Сохранить</strong> → <strong>Пробный чек</strong> и <strong>Пробная этикетка</strong>.</li><li>Считайте штрихкод пробной этикетки сканером — должен быть «бип».</li></ol><p><img src="'+r+'" alt="Принтеры"></p><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><ul><li>Если принтер выбран — чек и этикетка печатаются <strong>сразу, без окна печати</strong>.</li><li>Если принтер не выбран («Окно печати») — при каждой печати открывается окно печати Windows, работает с любым принтером.</li><li>Если принтер выключен или закончилась бумага — появится ошибка и предложение <strong>«Через окно печати»</strong>. Чек не пропадает.</li></ul><h2 id="problemler" tabindex="-1">Проблемы <a class="header-anchor" href="#problemler" aria-label="Permalink to &quot;Проблемы {#problemler}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Признак</th><th>Что делать</th></tr></thead><tbody><tr><td>«Выбранный принтер не найден»</td><td>Принтер подключён и включён? Выберите его заново в настройках.</td></tr><tr><td>Этикетка печатается на двух этикетках / остаётся пустое место</td><td>«Размер этикетки» должен совпадать с рулоном. Откалибруйте датчик принтера (Xprinter: включите, удерживая кнопку FEED).</td></tr><tr><td>Штрихкод не считывается</td><td>Почистите термоголовку; на этикетке 30×20 штрихкод мелкий — 40×30 лучше.</td></tr><tr><td>Денежный ящик не открывается</td><td>Ящик подключается к разъёму RJ11 принтера чеков (у некоторых принтеров этикеток этого разъёма нет). Проверьте кнопкой «Открыть ящик».</td></tr></tbody></table>',9)])])}const u=o(n,[["render",i]]);export{m as __pageData,u as default};
